quests[45404] = { id = 45404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panik in der Brauerei", description = "Auf einen Überraschungsangriff waren wir nicht vorbereitet. Ich befürchte, Braumeisterin Blanche wurde gefangen genommen... oder gar Schlimmeres.\n\nHelft mir bitte, <Großmeister/Großmeisterin>!", sourceObjective = "Helft Almai bei der Suche nach Braumeisterin Blanche und verteidigt die Brauerei Sturmbräu.", completion = "Wie konnte uns das nur geschehen? Wie konnte MIR das geschehen? Ich hätte nie gedacht, dass ich so jung sterben würde... und so gewaltsam...\n\nWir haben versucht, unsere gefallenen Freunde vom Gift zu befreien, aber es ist zu stark.\n\nIch kann nicht ruhen, solange das Überleben meines Ordens nicht gesichert ist. Es tut mir leid, dass ich Euch enttäuscht habe, Großmeister {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[45405] = { id = 45405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bresche in das Sanktum", description = "Die Zeit ist gekommen. Valtrois ist bereit, den Schild zu zerstören, der die Bresche im Sanktum schützt. Ich teleportiere Euch zur Bresche, von dort müsst Ihr den Bereich sichern.\n\nNehmt diese Telemantiekugeln. Falls Ihr Unterstützung braucht, könnt Ihr damit Verdorrte beschwören.\n\nWir müssen zuschlagen, bevor der Feind neue Verteidigungsmaßnahmen einleiten kann. Lasst mich wissen, wenn Ihr bereit seid, und wir beginnen.", sourceObjective = "Sprecht mit Oculeth, um den Angriff zu starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45406] = { id = 45406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Sturms", description = "Wir haben keine Zeit mehr, uns vorzubereiten, denn die Zeit zum Handeln ist gekommen!\n\nKommt und begleitet mich. Wenn Ihr mir helft, den Feind ins Visier zu nehmen, werden wir diese Insel mit Donner und Blitzen säubern!", sourceObjective = "Vernichtet die Truppen der Brennenden Legion auf der Schildruhinsel.", completion = "Der heutige Tag ist nicht Euer Ende. Die Legion bedroht die Pforte der Tapferkeit, aber sie hat nichts, was Eurer Kraft nahekommt. Sie wird sicher scheitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[45412] = { id = 45412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schutz: Hilfe durch die Illidari", description = "Zum Glück sind wir nicht die Einzigen, die die Verschwörungen der Legion zur Infiltration der Stadt aufdecken.\n\nKor'vas Blutdorn von den Illidari hat begonnen, alleine die Straßen zu patrouillieren, um den Ursprung der jüngsten Angriffe aufzuspüren.\n\nSo ganz traue ich diesen \"Dämonenjägern\" nicht über den Weg, aber immerhin haben sie ihrem Namen alle Ehre gemacht. Ich schlage vor, Ihr sucht sie auf und seht, was sie herausgefunden hat, bevor die Legion erneut zuschlägt.", sourceObjective = "Findet Kor'vas Blutdorn in den Straßen von Dalaran.", completion = "Ihr... Euch habe ich doch draußen auf den Inseln gesehen.\n\nWir müssen uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45413] = { id = 45413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationen sammeln", description = "Die Legion hat einen Dämon nach dem anderen geschickt, um in die Tresore der Kirin Tor in der Stadt einzubrechen, aber wir wissen nicht, worauf sie es abgesehen haben.\n\nAllem Anschein nach haben sie es schlussendlich geschafft, hineinzugelangen.\n\nWir müssen herausfinden, was gestohlen wurde, und zwar schnell, bevor sie dieses Etwas benutzen können.\n\nBefragt alle Überlebenden. Ich werde mithilfe meiner Geistersicht sicherstellen, dass nicht noch Dämonen hier sind und uns irgendwo auflauern.", sourceObjective = "Befragt Bürger in der Bank von Dalaran, um herauszufinden, was gestohlen wurde.", progress = "Wir können nicht noch einen Angriff riskieren, bis wir die Sache ergründet haben.", completion = "Nein... nein, nein, nein, nein!\n\nNicht gut. Gar nicht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[45414] = { id = 45414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdachtsmomente bestätigen", description = "Das Herz ist das letzte Überbleibsel von Hochlord Kruul, der einst einer der besten Kriegsfürsten der Legion war.\n\nVor vielen Jahren hätten sich Kruuls Armeen beinahe auf das Dunkle Portal gestürzt, um Azeroths Angriff auf die Scherbenwelt im Keim zu ersticken. Wir Illidari haben ihn abgefangen, bevor er zuschlagen konnte.\n\nIch fürchte, dass die Legion das Herz dazu verwenden will, Kruuls Wiederbelebung im Nether zu beschleunigen. Wir müssen sofort Prophet Velen aufsuchen. Nur er kann uns das mit Sicherheit sagen.", sourceObjective = "Findet Prophet Velen in Dalaran.", completion = "Kruul darf diese Welt nicht betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45415] = { id = 45415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwischen den Welten", description = "Kruul rühmt sich der Verdammnis, aber seine Macht hat sich noch nicht vollkommen manifestiert. Seine Diener haben sein Herz gestohlen, um seine Wiedergeburt im Nether zu beschleunigen.\n\nWir haben nicht viel Zeit.\n\nBegebt Euch zu der Stelle an den Stufen des Schicksals in der kargen Scherbenwelt, wo Kruul gefallen und die Verbindung zu seiner Seele am stärksten ist. Dort müsst Ihr den Weg in sein Reich öffnen.\n\nIch muss mich auf den bevorstehenden Kampf vorbereiten. Viel Glück, Champion.", sourceObjective = "Öffnet ein Portal in den Wirbelnden Nether an den Stufen des Schicksals in der Scherbenwelt.", completion = "Wir müssen zuschlagen, bevor Kruul zu voller Macht erstarkt, aber wir werden Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45416] = { id = 45416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Hochlords", description = "Ich habe ein Schreiben von Kor'vas für Euch und Anweisungen, wie ich Euch dorthinbringe.\n\nIch kann Euch zu ihnen teleportieren, um den Kampf zu beginnen, aber Ihr werdet einige Nethersplitter benötigen, um Euch den Weg in den Wirbelnden Nether zu erzwingen.\n\nWenn Ihr genug davon in Eurem Besitz habt, sprecht mit mir und Ihr könnt beginnen.", sourceObjective = "Besiegt Hochlord Kruul im Wirbelnden Nether. Sprecht mit Kriegsrätin Victoria, um dorthinzugelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45417] = { id = 45417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Herr des Schattenrats", description = "Gul'dan missbraucht in diesem Augenblick die Macht des Nachtbrunnens, um Sargeras in unsere Welt zu holen.\n\nVersammelt Eure Gefährten und kämpft Euch zur Spitze der Nachtfestung durch.\n\nIch werde das Herz des Lichts vorbereiten und zu Euch stoßen, wenn die richtige Zeit gekommen ist.\n\nZusammen werden wir Gul'dan ein für alle Mal zur Strecke bringen.", sourceObjective = "Besiegt Gul'dan in der Nachtfestung.", completion = "Ein angemessenes Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[45420] = { id = 45420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtfestung: Das Auge von Aman'thul", description = "Die Schlacht ist gewonnen, aber der Krieg ist noch lange nicht vorbei.\n\nWenn wir die Flut an Dämonen eindämmen wollen, die sich über Azeroth ergießt, müssen wir mit Hilfe der Säulen der Schöpfung das Grabmal des Sargeras versiegeln.\n\n<Khadgar senkt seinen Blick auf das Auge von Aman'thul.>\n\nDas... dürfte zu schwer sein, um es zu tragen.\n\nVielleicht kann ich die Macht des Auges selbst verwenden, um es nach Dalaran zu teleportieren. Nun, es gibt nur einen Weg, das herauszufinden!", sourceObjective = "Helft Khadgar dabei, das Auge von Aman'thul zu transportieren.", completion = "Jetzt, da sich das Auge von Aman'thul in unserem Besitz befindet, sind wir unserem Ziel, das Portal zu versiegeln, einen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45421] = { id = 45421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Dirge of Asgrim" }
quests[45422] = { id = 45422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edikt des Gottkönigs", description = "Unsere Späher berichten von beunruhigenden Vorgängen in Sturmheim.\n\nGottkönig Skovald hat neue Befehle von Gul'dan erhalten und seine Truppen haben in der Folge die Anzahl ihrer Angriffe erhöht.\n\nWir müssen herausfinden, was genau in Gul'dans Nachricht stand, {name}.\n\nTrotz der neuen Befehle ist Gottkönig Skovald immer noch davon besessen, die Gunst des Titanenhüters Odyn zu erlangen. Stellt Skovald in den Hallen der Tapferkeit, um in Erfahrung zu bringen, was seine Legionsmeister von ihm verlangen.", sourceObjective = "Bezwingt Gottkönig Skovald in den Hallen der Tapferkeit auf dem Schwierigkeitsgrad 'Mythisch'.", sourceObjectiveStatus = "unverified-source-field" }
quests[45423] = { id = 45423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winzlinge des Wehklagens", description = "Ich bin froh, dass Ihr da seid, {name}.\n\nSeit dem Erwachen von Naralex lässt sich immer wieder ein schwaches Jaulen aus den Höhlen vernehmen. Zuerst dachten wir, dass irgendwelche von den mutierten Kleintieren überlebt hätten. Aber unsere Untersuchungen haben ergeben, dass sie wesentlich größer geworden sind und sich explosionsartig vermehrt haben! Es könnte mit der Leiche von Verdan dem Ewiglebenden zusammenhängen, aber das wissen wir nicht sicher. Und darum schicken wir Euch rein.\n\nAußerdem habe ich vor Kurzem verdächtige Fußspuren gesehen, die in die Höhlen hineinführten. Wir sind vielleicht nicht allein, also passt gut auf Euch auf.", sourceObjective = "Besiegt die keimende ewiglebende Spore in den Höhlen des Wehklagens.", completion = "Ja, ich habe diesen verdächtigen Kerl auch gesehen. Er ist an mir vorbeigelaufen. Wahrscheinlich ein Tauren, aber ich bin mir nicht sicher. Haltet Ausschau nach ihm. Irgendetwas sagt mir, dass wir gerade erst anfangen, dieses Rätsel zu lösen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45425] = { id = 45425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Hain", description = "Also DAS war doch mal echt gut. Jetzt, da wir den Kommandanten ausgeschaltet haben, sollten die Druiden und die Ahnen vorläufig sicher sein. Rache war ein zusätzlicher Bonus.\n\nWir sollten zu Rensar zurückkehren und ihm berichten, was wir erreicht haben.", sourceObjective = "Kehrt zu Rensar Großhuf im Hain der Träume zurück.", completion = "Wir haben Euch in den letzten Monaten viel abverlangt, {name}. Ihr habt unsere Erwartungen nicht nur erfüllt, sondern übertroffen. Indem Ihr Katith'rax getötet habt, wurden die Angriffe auf unsere Ahnen gestoppt.\n\nIhr verdient Eure Stellung als Erzdruide des Hains der Träume. Ich fühle mich geehrt, Euer Amtsbruder zu sein und erwarte, dass wir noch viel für diese Welt bewirken werden. Gemeinsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[45426] = { id = 45426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorstoß der Natur", description = "{name}, Ihr müsst zum Hain der Träume zurückkehren und dort von dem Angriff auf mich berichten. Sagt den anderen Druiden, dass Übergriffe wie diese gegen uns fortgesetzt werden, wenn wir keinen Weg finden, die Legion aufzuhalten.\n\nIch danke Euch für die Hilfe. Ich spüre, wie die Teufelsenergien aus meinen Adern weichen, obwohl das noch einige Zeit andauern wird.", sourceObjective = "Kehrt zu Rensar Großhuf im Hain der Träume zurück.", completion = "Welche Neuigkeiten bringt Ihr über den Angriff auf Avianas Schrein?", sourceObjectiveStatus = "unverified-source-field" }
quests[45427] = { id = 45427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
