quests[45436] = { id = 45436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Win of the Day (Skirmish)" }
quests[45437] = { id = 45437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine drängende Situation", description = "<Erzmagier/Erzmagierin> {name}! Wir haben einen wichtigen Gast. Bitte sucht mich in meinem Gemach auf, wenn Ihr etwas Zeit erübrigen könnt.", sourceObjective = "Findet Meryls Besucher in der Halle des Wächters.", completion = "Ich wurde ungerechterweise von vielen verleumdet. Ich bin froh, dass die Tirisgarde niederträchtigen Gerüchten keinen Glauben schenkt!", sourceObjectiveStatus = "unverified-source-field" }
quests[45439] = { id = 45439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Invasion von... Murlocs?" }
quests[45440] = { id = 45440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da braut sich etwas zusammen", description = "Seid gegrüßt, <Großmeister/Großmeisterin>. Ich bin Experte für die Herstellung komplizierter Gebräue, und Almai und ich haben mit der Brauerei Sturmbräu zusammengearbeitet, um Sturmgebräu für den Orden herzustellen.\n\nUm genau zu sein, haben wir bereits mit der Produktion begonnen!\n\nDas schreit nach einem Fest, meint Ihr nicht auch? Wir haben von meinem preisgekrönten Festtagsbräu genug für alle mitgebracht!", sourceObjective = "Weist die Brauer der Brauerei Sturmbräu an, Festtagsbräu zu verteilen, und zwar auf der Terrasse des Tempels, vor dem Lachenden Kranich und in der Nähe des Übungsplatzes.", progress = "Puh. Das Festtagsbräu ist... *hicks* schtärker, als isch es in Erinnerung hatte. *rülps*", completion = "Puh. Das Festtagsbräu ist... kräftiger, als ich es in Erinnerung hatte. *rülps*", sourceObjectiveStatus = "unverified-source-field" }
quests[45441] = { id = 45441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ätzende Larven - ÜBERARBEITEN", description = "Eure Bitte, Holz zu schlagen, scheint durchaus annehmbar, {name}. Außerdem gibt es etwas, das Ihr für mich tun könnt.\n\nEs gibt eine Mottenart, deren Larven sich von Bäumen ernähren. Normalerweise sind es zu wenige, um wirklich Schaden anzurichten, aber einmal in jedem Jahrhundert vermehren sie sich in überwältigendem Maße.\n\nDas Massenschlüpfen hat gerade begonnen. All meine Hüter kämpfen gegen den Alptraum und ich kann sie nicht entbehren. Ich fürchte, ich kann die Waldriesen nicht allein schützen.\n\nWürdet Ihr die Larven zertrampeln?", sourceObjective = "Zertrampelt 50 ätzende Larven.", sourceObjectiveStatus = "unverified-source-field" }
quests[45442] = { id = 45442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflisches Unwohlsein", description = "Also... Yserallinensamen zur Heilung, Beulengras als Gegengift und Elementarerde zur Krankheitsabwehr. Oh, und ein Hauch von gemahlener Teufelswurz zur Abstimmung.\n\nJa, ich glaube, das wird dem Gift der Legion entgegenwirken. Es wird wahrscheinlich furchtbar schmecken, aber welche Medizin tut das nicht?\n\nBeeilt Euch, <Großmeister/Großmeisterin> {name}. Unseren schwer angeschlagenen Freunden bleibt nicht mehr viel Zeit.", sourceObjective = "Benutzt Blanches Destille und gebt dann 8 teufelsvergifteten Initianden das kurierende Gebräu.", progress = "Hat unser kurierendes Gebräu gewirkt?", completion = "Mein Herz ist voller Glück darüber, wie unser Orden wieder gesundet.", sourceObjectiveStatus = "unverified-source-field" }
quests[45447] = { id = 45447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turned In Marin's Coin" }
quests[45449] = { id = 45449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemistin Korlya", description = "Die Zeloten der Teufelsgarnison werden von Alchemistin Koryla angeführt. Es ist wahrscheinlich, dass sie diejenige war, die von Braumeisterin Blanche bei der Vergiftung unseres Gebräus beobachtet wurde.\n\nBitte tötet sie.", sourceObjective = "Tötet Alchemistin Koryla.", completion = "Ich danke Euch. Das wäre ein Dämon weniger, der gegen uns angehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[45459] = { id = 45459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Legion", description = "Ich habe mein Bestes gegeben, um die Dämonen in die Flucht zu schlagen, aber selbst für meine Fähigkeiten waren es zu viele...\n\nAls ich im Sterben lag, hörte ich, wie der Schreckenslord einem Alchemisten der Teufelsskorn befahl, mein Gebräu zu vergiften und dann zur Verheerten Küste zurückzukehren.\n\nWenn Ihr etwas von dem Gift an Euch bringen könntet, wären wir sicher in der Lage, ein Gegenmittel zusammenzubrauen!", sourceObjective = "Sprecht mit Tak-Tak, um zur Verheerten Küste zu reisen.", completion = "Gut, Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[45460] = { id = 45460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
