quests[45479] = { id = 45479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kosumoth the Hungering" }
quests[45482] = { id = 45482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkan: Das Schicksal der Wellenskorn", description = "Gestern ist ein Kundschafter aus Sturmheim mit einer bedeutenden Entdeckung eingetroffen: diesen antiken Schriftrollen. Sie enthalten eine Prophezeiung der Valkyra über eine neue Anführerin der Vrykul... eine, die die Wellenskorn in den Kampf gegen die Legion führen könnte.\n\nWas die Sache kompliziert macht, ist die Tatsache, dass sie womöglich die Nachfahrin von Skovald ist.\n\nNehmt diese Schriftrollen, findet die Nachfahrin und bringt sie zu den Valkyra. Ich glaube, die in der Prophezeiung erwähnten Verbannten sind die Vrykul von Jandvik. Das wäre also ein guter Ausgangspunkt für Eure Suche.", sourceObjective = "Sucht Jandvik auf, um die in den Schriftrollen erwähnte Vrykul zu finden.", completion = "Und was habt Ihr hier zu suchen, Fremdling?", sourceObjectiveStatus = "unverified-source-field" }
quests[45483] = { id = 45483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ealdis" }
quests[45484] = { id = 45484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harbinger of Screams" }
quests[45485] = { id = 45485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aodh Witherpetal" }
quests[45486] = { id = 45486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die widerstrebende Königin", description = "Moment, woher wisst Ihr von meiner Abstammung? Achtet auf Eure Worte hier, denn nicht wenige würden Jagd auf mich machen, wenn sie von meiner Blutlinie wüssten.\n\nIch weiß nicht, wer Ihr seid, und ich glaube nicht, dass ich Teil irgendeiner Prophezeiung bin. Wenn Ihr aber beabsichtigt, den Schaden, den mein Vater den Wellenskorn zugefügt hat, wiedergutzumachen, fühle ich mich verpflichtet, Euch zu helfen.\n\nTrefft mich in Valdisdall, {class}. Von dort aus können wir uns nach Skold-Ashil begeben und eine Audienz bei Eyir erbitten. Vielleicht kann sie Licht in diese Prophezeiung bringen.", sourceObjective = "Bringt Sigryn zu Eyir in Skold-Ashil.", progress = "Ja, Kind?", completion = "Danke, dass Ihr Sigryn zu mir gebracht habt, Fremder. Sie verkörpert die Zukunft unseres Volkes.\n\nUnd gleichwohl Ihr schon so viel für uns getan habt, möchte ich Euch um einen weiteren Gefallen bitten. Bitte steht Sigryn bei ihren Herausforderungen bei. Sie hat Vertrauen in Euch gefasst und braucht jemanden, der sie durch die anstehenden Prüfungen geleitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[45487] = { id = 45487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabxach" }
