quests[45498] = { id = 45498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Hunde soll man nicht wecken", description = "Seht Ihr die großen Eredar da drüben? In dem Grabhügel befindet sich Goldrinn! Ich will gar nicht wissen, was die Legion ihm darin antut, aber ich bin sicher, wir wollen nicht, dass sie Erfolg haben.\n\nGehen wir hinein und retten Goldrinn!", sourceObjective = "Rettet Goldrinn aus Sturmgrimms Grabhügel.", completion = "Wir haben es geschafft! Wir haben Goldrinn gerettet!", sourceObjectiveStatus = "unverified-source-field" }
