quests[45520] = { id = 45520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Portalen" }
quests[45522] = { id = 45522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochensprecher zum Schweigen bringen", description = "Sigryns Anspruch auf den Thron wird ihr von zwei Rivalen streitig gemacht: Runenseher Faljar von den Knochensprechern und Jarl Velbrand von den Drekirjar.\n\nIch würde in Haustvald mit dem Runenseher beginnen. Er war ein enger Verbündeter von Skovald und ist ein mächtiger Mystiker. Mit den Knochensprechern unter seinem Kommando wird er sich als unerschrockener Gegner erweisen, falls man ihn nicht zum Einlenken bewegen kann.\n\nGeht und nehmt Euer Schicksal im Namen der Valkyra in die Hand!", sourceObjective = "Besiegt Runenseher Faljar in Haustvald.", completion = "Die Knochensprecher fügen sich. Unser Klan wird Sigryn ihren Anspruch auf den Thron nicht streitig machen.\n\nSeid vorsichtig, was sie angeht, {class}. Ich kann die Finsternis sehen, die Skovald verschlungen hat, wie sie im Herzen dieses Mädchens wohnt. Wie sie ihr bisher widerstanden hat, weiß ich nicht.\n\nIhr solltet alle Hoffnung darauf setzen, dass sie sie kontrollieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[45523] = { id = 45523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drekirjar zähmen", description = "Die Worte des Knochensprechers beunruhigen mich. Die Finsternis, von der er spricht... Skovalds Teufelsfluch... Wäre es möglich, dass er ihn irgendwie an mich weitergegeben hat?\n\nNein, das kann nicht sein. Der Runenseher muss sich geirrt haben...\n\nKommt, der nächste Herausforderer wartet bereits. Ich werde zweifellos Eure Hilfe brauchen, um ihn ebenfalls gefügig zu machen.", sourceObjective = "Besiegt Jarl Velbrand in Hrydshal.", completion = "Ihr habt den Rückhalt der Drachenreiter, aber es gibt noch einen weit größeren Nebenbuhler um den Thron, im Verborgenen.\n\nDer Sohn des Gottkönigs lebt. Meine Reiter haben ihn unter den Ausgestoßenen von Vrekt entdeckt. Er wäre der wahre Erbe von Skovalds Thron.\n\nDie Vrykul würden Euch niemals folgen, sollte er Euch den Anspruch streitig machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45524] = { id = 45524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vergessene Erbe", description = "Mein Bruder... lebt?\n\nAls ich ihn das letzte Mal sah, war er von Meuchelmördern umzingelt. Ich kann mir nicht vorstellen, wie er sie besiegt hat...\n\nWir sollten nach Vrekt reisen. Ich möchte meinen Bruder mit eigenen Augen sehen.", sourceObjective = "Findet Torvald in Vrekt.", progress = "Lasst uns zu Vrekt gehen.", completion = "Ich kann nicht glauben, dass ich meinen Bruder lebendig vorfinde, nur um ihn durch meine eigene Klinge fallen zu sehen.\n\nWie kann das Schicksal nur so grausam sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[45525] = { id = 45525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbeantwortete Fragen", description = "Was getan ist, ist getan. Es ist niemand anderes mehr da, der Anspruch auf den Thron der Wellenskorn erheben könnte.\n\nDie Worte meines Bruders verfolgen mich allerdings immer noch. Wenn Eyir weiß, wer den Befehl gegeben hat, meine Familie zu töten, dann habe ich es verdient, das zu wissen.\n\nKommt, lasst uns zurückreisen.", sourceObjective = "Gesellt Euch zu Sigryn in der Kammer von Eyir in Skold-Ashil.", completion = "Sigryn hat denselben Pfad eingeschlagen wie Skovald vor ihr. Allerdings fürchte ich, dass sie viel mächtiger ist, als ihr Vater es je gewesen ist.\n\nIch habe Angst, dass Sigryns Rachedurst ihr Verderben sein könnte. Obwohl sie wahrhaftig mächtig ist, wäre sie keine Gegnerin für Odyn.\n\nSie muss aufgehalten werden, bevor es zu spät ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[45526] = { id = 45526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Gottkönigin", description = "{class}t, die Kirin Tor haben einen Weg gefunden, Euch in die Hallen der Tapferkeit zu bringen, damit Ihr die Erbin des Gottkönigs verfolgen könnt. Erzmagier Khadgar hat mich gebeten, Euch noch einmal eindringlich darauf hinzuweisen, wie wichtig es ist, Sigryn aufzuhalten, da die Prophezeiungen andeuten, dass sie immer noch der Schlüssel sein könnte, um die Wellenskorn gegen die Legion zu vereinigen.\n\nEs wird unglaublich viel Energie verbrauchen, Euch direkt in die Hallen zu teleportieren, also sorgt dafür, dass Ihr vorbereitet seid. Es könnte einige Zeit dauern, bis wir Euch erneut hinschicken können.\n\nSprecht mit mir, wenn Ihr bereit seid, Euch aufzumachen.", sourceObjective = "Sprecht mit Kriegsrätin Victoria, um zu Sigryns Aufenthaltsort teleportiert zu werden und sie zu besiegen.", completion = "Ich... danke Euch, dass Ihr meinetwegen hergekommen seid. Ich hoffe, Ihr könnt mir das, was ich getan habe, verzeihen.\n\n\nIch werde zu Eyir zurückkehren. Ich hoffe nur, dass sie mir ebenfalls Vergebung gewähren kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[45527] = { id = 45527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyirs Vergebung", description = "Mir tut alles so leid, was Ihr meinetwegen durchmachen musstet. Nach meinen Taten hier fürchte ich, dass alles umsonst gewesen sein könnte.\n\nKehrt mit mir zurück nach Skold-Ashil. Dort werde ich jedes Urteil akzeptieren, das Eyir für angemessen hält.", sourceObjective = "Wohnt Eyirs Urteil über Sigryn in der Kammer von Eyir in Skold-Ashil bei.", completion = "Denkt nur, als ich Euch traf, hatte ich die volle Absicht, meine Tage als Bäuerin zu verbringen. Ich ahnte nicht, dass die Götter andere Pläne für mich hatten.\n\nDanke, dass Ihr mir meine wahre Bestimmung gezeigt habt. Ich kann nur hoffen, dass ich Eyirs Erwartungen erfüllen und die Wellenskorn wiedervereinigen kann.\n\nSollte dieser Tag kommen, wird die Legion es bereuen, Sturmheim jemals betreten zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[45528] = { id = 45528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geschändeten Grabhügel", description = "Ihr habt zu lange gebraucht, da habe ich mir die Freiheit genommen, die Grabhügel vorab auf eigene Faust zu erkunden. Die Legion hat Portale errichtet und bringt ständig immer mehr Dämonen hindurch. Wir müssen sie schließen, damit wir Goldrinn retten können!\n\nIch bin nicht sicher, ob meine üblichen Methoden ausreichen werden, um sie zu schließen, aber ich denke, dass Ihr es schaffen könnt! Ich glaube, dass etwas Rankenarbeit vonnöten sein wird.", sourceObjective = "Schließt 3 Legionsportale in Sturmgrimms Grabhügel.", progress = "Wenn wir Kletterranken herbeirufen, um die Portale zu verschließen, kann die Legion nicht mehr hindurchkommen.", completion = "Jetzt können die Dämonen keine Verstärkung mehr rufen. Das war toll!", sourceObjectiveStatus = "unverified-source-field" }
quests[45531] = { id = 45531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriechende Teufelsmagie" }
quests[45532] = { id = 45532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutters Befehle", description = "Das große, hässliche Ding sieht aus, als ob es den Angriff hier anführt. Bringen wir es zur Strecke!", sourceObjective = "Tötet Mutter Mirenda.", completion = "Was hat sie über eine Ablenkung gesagt?! Das klingt gar nicht gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[45533] = { id = 45533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion Dungeon Reward Quest" }
quests[45534] = { id = 45534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gemeinsamer Feind", description = "Ich habe eine weitere Bitte an Euch, <Fremder/Fremde>.\n\nKehrt zu Euren Anführern zurück und erzählt ihnen davon, was hier geschehen ist. Eure Leute werden vielleicht niemals echte Verbündete der Wellenskorn sein, aber wir haben einen gemeinsamen Feind. Und diesen wird mein Volk bis zum letzten Vrykul bekämpfen.\n\nIch hoffe, Euch auf dem Schlachtfeld zu sehen, wenn die Zeit gekommen ist.", sourceObjective = "Kehrt zu Khadgar in der Violetten Zitadelle zurück.", completion = "Beeindruckend! Dann war also doch etwas an dieser Prophezeiung dran!\n\nIch bin froh, dass Sigryn die Vrykul anführen wird und nicht diese Unholde, die sich ihr entgegengestellt haben. Lasst uns hoffen, dass sie die Wellenskorn unter ihrem Banner vereinen kann, bevor die Legion alles überrannt haben wird.\n\nGut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[45536] = { id = 45536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "2vs2-UI (Wöchentliche Quest)" }
quests[45537] = { id = 45537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "3vs3-UI (Wöchentliche Quest)" }
quests[45538] = { id = 45538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "10vs10-UI (Wöchentliche Quest)" }
quests[45539] = { id = 45539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkampfherausforderung: Die Höhlen des Wehklagens", description = "Diese mutierten Kleintiere in den Höhlen des Wehklagens vermehren sich weiter in der Dunkelheit des Sumpfes, aber ich habe mein Bestes gegeben, sie zu dezimieren.\n\nAuf meinem Weg durch die Höhlen habe ich ein paar Haustiere und Bedarfsgegenstände gefunden. Solltet Ihr meinen besten Durchgang übertreffen, lobe ich einen Sack Haustierbedarf als Preis aus.\n\nWenn Ihr mich schlagen wollt, müsst Ihr alle Gegner in den Höhlen ausschalten, ohne Eure Haustiere zu heilen oder wiederzubeleben. Viel Glück!", sourceObjective = "Besiegt die keimende ewiglebende Spore in den Höhlen des Wehklagens.", completion = "Also, das war wirklich beeindruckend! Hier ist der Sack mit Haustierbedarf. Ihr habt ihn Euch verdient! Tut mir leid, dass er so feucht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[45540] = { id = 45540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hilferuf aus der Höhle", description = "Oh, sehr gut, ich bin froh, dass Ihr da seid. Wir haben ein paar beunruhigende Gerüchte über erneut auftretende Verderbnis in den Höhlen des Wehklagens gehört. Und Ihr scheint genau die richtige Person zu sein, die dies untersuchen könnte.\n\nSeit Naralex' Erwachen hat eine seiner Schülerinnen die Gegend überwacht, um die mutierten Tiere unter Kontrolle zu halten. Sie war es, die uns diese dringenden Warnungen zukommen ließ.\n\nTrefft Euch mit ihr im Auge des schädelförmigen Felsens oberhalb der Höhlen des Wehklagens und bietet ihr Eure Hilfe in dieser Situation an.", sourceObjective = "Findet Muyani im schädelförmigen Felsen oberhalb der Höhlen des Wehklagens.", completion = "Danke, dass Ihr gekommen seid. Ich habe ein paar interessante Neuigkeiten über die Vorfälle in den Höhlen des Wehklagens nach dem Erwachen von Naralex.", sourceObjectiveStatus = "unverified-source-field" }
quests[45541] = { id = 45541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie gefällt EUCH das?!" }
quests[45542] = { id = 45542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Portalen" }
quests[45545] = { id = 45545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasswurf", description = "Die Legion verteidigt den Unterschlupf der Teufelsskorn mit Teufelsemittern. Zum Glück haben wir noch Sturmgebräu übrig. Es sollte genug da sein, um sie damit zu zerstören.\n\nNehmt dieses Fass, werft es auf die Kondensatoren und seht zu, wie sie in die Luft fliegen. BUMM!", sourceObjective = "Benutzt Sturmgebräu, um 5 Teufelsgebräukondensatoren zu zerstören.", completion = "Dämonen in die Luft zu jagen wird nie langweilig, oder? Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[45546] = { id = 45546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Attempt Used" }
quests[45549] = { id = 45549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgung der Verderbnis" }
quests[45550] = { id = 45550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgung der Verderbnis" }
quests[45551] = { id = 45551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verheerende Auswirkungen", description = "Die Brennende Legion wird nicht ruhen, bis sie alles und jeden vernichtet hat. Ihre Gegenwart hier hatte bereits verheerende Auswirkungen auf unser Land und jetzt offensichtlich auch auf die Wildtiere hier.\n\nIch habe zahlreiche Berichte über erkrankte Tiere im Dickicht um die von den Dämonen heimgesuchte Stadt Suramar erhalten.\n\nBegebt Euch dorthin und geht diesen Gerüchten nach.", sourceObjective = "Führt Untersuchungen in Suramar durch.", completion = "<Der Begleiter von Nachtjägerin Syrenne ist zu schwach, um auf Eure Anwesenheit zu reagieren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45552] = { id = 45552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wundpflege", description = "<Aufgrund seiner Wunden kann sich D'Bynn nicht bewegen.>\n\nVielleicht könnt Ihr etwas in der Nähe finden, um die Wunden des Manasäblers zu versorgen?", sourceObjective = "Verwendet die an den Leylinien im Purpurdickicht gefundenen Manawurzeln, um D'Bynns Wunden zu versorgen.", completion = "<D'Bynn schmiegt sich an Eure Hand.>", sourceObjectiveStatus = "unverified-source-field" }
quests[45553] = { id = 45553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Nachtjägerin", description = "<D'Bynn nimmt die Stimme seiner Meisterin wahr. Mit seiner Schnauze stupst er Euch nachdrücklich an, um Euch aufzufordern, auf seinen Rücken zu steigen.>", sourceObjective = "Reitet D'Bynn und lasst ihn Euch zu Nachtjägerin Syrenne bringen.", completion = "Ich muss Euch wohl danken, dass Ihr meinen geliebten Gefährten gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45554] = { id = 45554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übernahme der Befehlsgewalt", description = "Als Gefangener dieses Mistkerls Relyn bin ich in diesem Käfig hier fast verdorrt.\n\nEr ist Anführer einer Gruppe Nachtgeborener, die mit Hilfe von Teufelsmagie die hiesigen Wildtiere verderben und kontrollieren wollen.\n\nDer Einfluss der Brennenden Legion verbreitet sich bereits viel schneller, als mir lieb ist.\n\nTötet ihn und nehmt ihm seine Befehlskugel ab, damit ich aus diesem arkanen Gefängnis freikomme!", sourceObjective = "Tötet Folterer Relyn und verwendet seine Befehlskugel, um Nachtjägerin Syrenne zu befreien.", progress = "Diese magische Barriere lässt sich nur mit Relyns Befehlskugel durchbrechen.", completion = "Ich habe schon viele Fremde auf meinen Patrouillen durch die Stadt gesehen, aber keiner von ihnen war so tatkräftig wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[45555] = { id = 45555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenversklavte Wildtiere", description = "Dann handelt Relyn also auf Befehl von Lexera? Das überrascht mich nicht. Die Invasion der Dämonen in unserer Stadt schien sie nicht sonderlich beunruhigt zu haben.\n\nWir dürfen nicht zulassen, dass sie die Wildtiere von Suramar verdirbt. Ich habe geschworen, Suramar gegen alle Feinde zu verteidigen. Das beinhaltet auch jene innerhalb seiner Mauern.\n\nWenn Ihr Euch um ihre Fallensteller kümmert, werde ich versuchen, Nachtjägerin Lexera aufzuspüren.", sourceObjective = "Tötet Fallensteller der Nachtgeborenen und teufelsgeborene Fallensteller und befreit die dämonenversklavten Wildtiere.", completion = "Ihr versteht es immer wieder, mich zu überraschen, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[45556] = { id = 45556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zum Zuschlagen", description = "Ich bin einem der Fallensteller gefolgt, der mich somit ohne sein Wissen zur Verheerten Küste geführt hat.\n\nDort sah ich Lexera, inmitten einer Armee aus Dämonen und loyalen Nachtgeborenen.\n\nIch kam nicht nahe genug heran, aber soweit ich es sehen konnte, versuchen Lexera und ihre Fallenstellerarmee, die teufelsverderbten Wildtiere zu zähmen.\n\nDiese Perversion der Natur muss aufgehalten werden!\n\nTrefft mich an der Verheerten Küste und macht Euch bereit zum Zuschlagen. Ich werde noch mehr Manawurzeln sammeln. Ich habe das Gefühl, dass wir sie brauchen werden.", sourceObjective = "Trefft Euch mit Nachtjägerin Syrenne an der Verheerten Küste.", completion = "Wir müssen uns beeilen. Es wird nicht lange dauern, bis noch mehr Dämonen über diesen Pass kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45557] = { id = 45557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnatürliche Konsequenzen", description = "Lexera und ihre Fallensteller haben das Tal übernommen.\n\nSie ist stärker, als sie aussieht, {name}. Und sie kämpft mit der Stärke eines Schreckenslords. Ihr müsst gut vorbereitet sein.\n\nIch werde mich um diese Dämonen kümmern, während Ihr Lexera die Konsequenzen ihrer unnatürlichen Umtriebe aufzeigt.", sourceObjective = "Tötet Nachtjägerin Lexera.", completion = "Der Tod einer Nachtjägerin ist kein Grund zur Freude, aber es musste getan werden. In Wahrheit ist sie bereits gestorben, als sie sich mit der Brennenden Legion eingelassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[45559] = { id = 45559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter feindlichen Portalen" }
quests[45560] = { id = 45560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörung: Gepolter nahe Teufelstotem", description = "Die Tauren vom Hochbergstamm haben eine dringende Warnung übermittelt, die von ihren Verbündeten, den Drogbar, stammt. Die Teufelstotems verbreiten dämonische Verderbnis unter den Wildtieren in ihrer Umgebung und infizieren auch das Land selbst. Wir glauben, dass man dieser Sache lieber früher als später nachgehen sollte.\n\nDer Drogbarhäuptling Navarrogg kümmert sich persönlich darum und wir möchten, dass Ihr Euch mit ihm in der Nähe des Dorfs der Teufelstotems trefft.", sourceObjective = "Sucht Navarrogg am Nebelufer am Hochberg auf.", completion = "Ich danke Euch für Euer Kommen. Ich bin froh, dass Ihr diese Bedrohung ernst nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45561] = { id = 45561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommt zu mir", description = "Der Brief von Maximillian scheint auf einem Fetzen Schiffssegel geschrieben worden zu sein. Er beinhaltet Richtungsangaben zum Strand am nördlichen Hochberg.", sourceObjective = "Sucht nach Maximillian von Nordhain am Hochberg.", completion = "Seid Ihr bereit, anzufangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[45562] = { id = 45562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kniet nieder, Knappe!", description = "Ihr müsst vor mir niederknien, wenn wir unsere Reise ein weiteres Mal beginnen wollen. Also kniet nieder, damit ich Euch zum Knappen ernennen kann!", sourceObjective = "Kniet vor Maximilian nieder.", completion = "Sehr gut. Jetzt können wir beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45563] = { id = 45563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verhüllte Münze", description = "Ein wabernder Nebel umspielt die Münze und sie beginnt, über Eurer Handfläche zu schweben. Kurz klärt sich der Nebel auf und gibt den Blick auf eine Münze frei, die glänzt, als wäre sie frisch geprägt worden. Doch im nächsten Moment erscheint die Münze, als wäre sie über Jahre durch viele Hände gegangen. Als die Münze wieder auf Eurer Handfläche ruht, erscheinen Bilder von Dschungeln und wolkenverhangenen Gipfeln vor Eurem geistigen Auge. In der Vision erkennt Ihr die vier Erhabenen, die sich in einem Hof auf einer Insel versammelt haben.", sourceObjective = "Bringt die verhüllte zeitverzerrte Münze zu Nebelwirkerin Xia auf der Zeitlosen Insel.", completion = "Münzen sind wirklich interessante Gegenstände. Sie reisen durch das ganze Land, und diese hier scheint sogar durch die Zeit zu reisen.\n\nDass Ihr diese Münze genau dort gefunden habt, ist Omen und Segen zugleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[45564] = { id = 45564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die brennenden Vögel", description = "Die Teufelstotems experimentieren an diesen Falkosauriern herum! Sie haben nicht die gewünschten Ergebnisse erzielt und ihre Versuchsobjekte achtlos herumliegen lassen, damit sie die Tiere noch mehr vergiften.\n\nWir sollten die Totems einsammeln, die sie zurückgelassen haben, um weitere Verderbnis zu verhindern und herauszufinden, was sie genau getan haben.", sourceObjective = "Sammelt Totems der teuflischen Einwirkung ein.", progress = "Diese Tiere können nicht mit Teufelsmagie erfüllt werden, aber ich bezweifle, dass die Teufelstotems hier Halt machen werden.", completion = "Als ich mich hier umsah, waren dort einige Wachen. Ich bemerkte weitere merkwürdige Dinge auf der anderen Seite.\n\nZeigt mir diese Totems.", sourceObjectiveStatus = "unverified-source-field" }
quests[45565] = { id = 45565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterführende Ausbildung", description = "Es war eine gefährliche Reise, Knappe, voller Gefahren... Stürme, Dämonen, Sturmdämonen... Mich graust es beim Gedanken daran. Aber ich habe all diesen Gefahren trotzen können... unter Inkaufnahme großer persönlicher Opfer. Und da kommt Ihr ins Spiel.\n\nIhr müsst Euch aufmachen und meine Rüstung, meine Waffe und natürlich mein treues Ross retten. Wenn Ihr diese drei Aufgaben erledigt habt, werde ich Euch zum Knappen der Oberklasse ernennen!", sourceObjective = "Erledigt Maximillians Quests und tötet \"Dämonen\", um den Rang \"Knappe, Oberklasse\" zu erlangen.", completion = "Sehr gut, Knappe der Oberklasse! Jetzt beginnt die wahre Reise!", sourceObjectiveStatus = "unverified-source-field" }
quests[45566] = { id = 45566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Habseligkeiten eines Ritters", description = "Unter den Sturmböen und heranrauschenden Wellen stampfte und rollte mein mächtiges Schiff. Ritter niederen Standes hätten vor Furcht gezittert oder wären erstarrt. Aber ich nicht! Mitnichten! Heldenhaft streifte ich meine Rüstung ab und verwahrte sie sicher in meinem Sack.\n\nWarum ich mich bis auf die Unterwäsche auszog, fragt Ihr? Nur ein ignoranter Knappe würde so etwas fragen. Ich wollte natürlich verhindern, zusammen mit meinem Schiff auf den Meeresboden zu sinken!\n\nLeider aber wurden die Rüstungssäcke über Bord gespült.", progress = "Beschafft Maximillians Rüstung.", completion = "Sehr gut, Ihr habt meine Rüstung gefunden." }
quests[45567] = { id = 45567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Königreich für ein Pferd", description = "Oh, weh mir! Gleich nach der Landung führte ich einen Erkundungsritt auf meinem treuen Ross Pimento in das Herz eines dämonenverseuchten Dorfes im Norden durch. Dort angekommen band ich Pimento an, um meine Untersuchungen zu Fuß fortzusetzen. Als ich aber zu meinem Pferd zurückkehrte, musste ich feststellen, dass ein mächtiger Dämon es gestohlen hatte und auf ihm saß, als würde es ihm gehören! Bitte findet mein Ross und schickt es zu mir zurück.", sourceObjective = "Bringt Pimento zurück.", completion = "Pimento! Ihr habt ihn gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[45568] = { id = 45568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Excaliberto gestohlen!", description = "Auf meinen Erkundungen in einem Dorf in der Nähe wurde ich angegriffen. Sie haben mir mein Artefakt abgenommen! Wenn ich hier fortgehe, ist diese Küste natürlich ohne jegliche Verteidigung. Die Dämonen in der Nähe haben das Artefakt. Zieht los, tötet sie und holt es mir zurück!", sourceObjective = "Findet Excaliberto und bringt die Waffe zu Maximillian zurück.", progress = "Findet Maximillians \"Artefaktwaffe\" Excaliberto.", completion = "Ja!", sourceObjectiveStatus = "unverified-source-field" }
quests[45570] = { id = 45570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In sichereren Händen", description = "Wir müssen noch die Sache mit der fokussierenden Iris klären. Bitte bringt sie Euren Freunden bei den Kirin Tor zurück und richtet meine Entschuldigung aus.\n\nUnd ich werde wohl erst einmal Abstand vom Artefaktesammeln nehmen. Einmal von einem unsterblichen, bösen Schatten besessen gewesen zu sein, reicht mir fürs Erste.", sourceObjective = "Bringt die fokussierende Iris zu Erzmagier Kalec in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Endlich ist die fokussierende Iris wieder da! Nun, da ich sie in der Sicherheit unserer Tresore weiß, werde ich besser schlafen können.\n\nEs tut mir leid für Xylem, aber ich freue mich, dass er diese Tortur überlebt hat. Er ist vielleicht ein Exzentriker, aber er hat das Herz am rechten Fleck.\n\nIn den kommenden Kriegen werden wir mehr Verbündete wie ihn brauchen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[45571] = { id = 45571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Spionage", description = "Da wir jetzt das Schießpulver haben, sollten wir nun unseren nächsten Plan umsetzen. Wir werden uns an der Verheerten Küste treffen.\n\nAn Krasus' Landeplatz könnt Ihr einen Flug direkt zum nächsten Zielort erhalten. Wir sehen uns dann dort, {class}t.", sourceObjective = "Sprecht mit Aludane Wolkenweiß bei Krasus' Landeplatz, um zur Verheerten Küste zu fliegen.", completion = "Gut, dass Ihr da seid. Lasst uns mit der Arbeit beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45572] = { id = 45572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellung halten", description = "Wir haben zwar mit starker Gegenwehr der Legion gerechnet, aber unsere Angriffe auf ihre Lager haben ihre Truppen noch stärker erzürnt als erwartet. Unsere Einheiten sammeln sich sowohl am Boden als auch am Himmel über Donnertotem, um zu versuchen, dort wieder Fuß zu fassen.\n\nVersucht, so viele Gegner wie möglich auszuschalten. Wenn wir Donnertotem gesichert haben, beginnen wir mit unserem Plan für den finalen Angriff.", sourceObjective = "Schlagt die Streitkräfte der Legion in Donnertotem zurück.", completion = "Wir müssen unserer Verbündeten gedenken, die am heutigen Tage gefallen sind, und ihnen zu Ehren unseren Kampf fortsetzen.\n\nJetzt ist die Zeit gekommen, {name}. Unsere Reiter sind bereit. Lasst uns der Brennenden Legion die wahre Stärke des Hochbergs demonstrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[45573] = { id = 45573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch da!", description = "Da wären wir, {class}t. Auf dieser Insel gibt es eine Höhle voller außergewöhnlich mächtiger Dämonen und ihrer Anführer. Wenn unser Plan aufgeht, werden die Dämonen... \"ordentlich einen vor den Bug bekommen\", wie Tethys sich auszudrücken pflegt.\n\nWir haben jetzt keine Zeit, den ganzen Plan zu besprechen, aber Tess wird Euch beizeiten alles erklären. Als Erstes müsst Ihr diese Rampe hochstürmen und ein paar Gegner auf dem Weg ausschalten.", sourceObjective = "Tötet 8 Dämonen und erreicht das obere Ende der Rampe.", completion = "War doch kinderleicht, Schattenklinge. Und jetzt kommt der Plan zum Tragen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45574] = { id = 45574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Zutaten", description = "Unsere Späher haben ein Teufelsskornlager innerhalb der Teufelsgarnison entdeckt. Wir werden so viele Proben des Teufelsgifts brauchen, wie wir finden können, wenn wir ein Heilmittel für unsere betroffenen Mönche zusammenbrauen wollen.\n\nNehmt Proben von allem, das auch nur ansatzweise nützlich aussieht!", sourceObjective = "Beschafft 5 Phiolen mit flüssiger Teufelsflamme, 3 Fläschchen mit Teufelsblut und 3 Prisen dämonische Asche.", progress = "Habt Ihr Proben gefunden, die wir gebrauchen können?", completion = "Hoffen wir, dass das ausreicht, um ein Heilmittel für unsere sterbenden Mönche zusammenzubrauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45575] = { id = 45575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorf der Verderber", description = "Die Teufelstotems erschaffen weiter Totems für zusätzliche \"Experimente\". Lasst uns mit diesen Einflößern auf althergebrachte Weise verfahren.\n\nIhr Tod wird ein großes Unrecht wiedergutmachen und Hinweise auf ihr letztendliches Ziel liefern.", sourceObjective = "Tötet Einflößer der Teufelstotems in Teufelstotem.", progress = "Man muss sich dieser Teufelstotems annehmen.", completion = "Tugar... Ich dachte, er sei tot. Er war schon vor dem Eintreffen der Legion ein widerwärtiger Bluttotem.\n\nWir müssen ihn loswerden.", sourceObjectiveStatus = "unverified-source-field" }
quests[45576] = { id = 45576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch da!", description = "Da wären wir, {class}t. Auf dieser Insel gibt es eine Höhle voller außergewöhnlich mächtiger Dämonen und ihrer Anführer. Wenn unser Plan aufgeht, werden die Dämonen... \"ordentlich einen vor den Bug bekommen\", wie Tethys sich auszudrücken pflegt.\n\nWir haben jetzt keine Zeit, den ganzen Plan zu besprechen, aber Lilian wird Euch beizeiten alles erklären. Als Erstes müsst Ihr diese Rampe hochstürmen und ein paar Gegner auf dem Weg ausschalten.", sourceObjective = "Tötet 8 Dämonen und erreicht das obere Ende der Rampe.", completion = "Ah, wie meine Klinge singt. Zeit, den Plan umzusetzen, Schattenklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[45583] = { id = 45583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadful Gladiator's Chain Armor" }
quests[45584] = { id = 45584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadful Gladiator's Dragonhide Armor" }
quests[45585] = { id = 45585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadful Gladiator's Dreadplate Armor" }
quests[45586] = { id = 45586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildverstärkung", description = "Es kann nicht schaden, den Schild des Seelensteins der Nachtgeborenen noch ein wenig zu verstärken. Um das zu erreichen, müssen wir ihn mit Energie durchtränken.\n\nRyanna hat mir versichert, dass Teufelsessenz wunderbar für unsere Zwecke geeignet ist. Ja, diese Methode ist ziemlich geschmacklos. Doch wie die Sin'dorei sehr wohl wissen, erfordern extreme Zeiten extreme Maßnahmen.\n\nEs ist ganz einfach: Wir benötigen dringend magische Energie und unsere Feinde besitzen diese im Überfluss.\n\nTut, was getan werden muss.", sourceObjective = "Benutzt den Seelenstein der Nachtgeborenen bei besiegten Teufelsgeborenen auf der Terrasse der Tränen.", completion = "Gut. Der Schild des Seelensteins sollte jetzt ausreichend verstärkt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[45587] = { id = 45587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrann der Teufelstotems", description = "Wenn ich gewusst hätte, das Tugar noch lebt und dahintersteckt, hätte ich Euch schon früher informiert! Er ist eine Kreatur voller Hass und bestimmt leicht für die Sache der Legion zu gewinnen.\n\nWenn er wirklich Erfolg mit seinen Teufelsexperimenten hat, müssen wir ihn jetzt aufhalten. Er verspottet uns von da oben. Auf geht's!", sourceObjective = "Findet Tugar Bluttotem und erledigt ihn.", completion = "Das war mächtige Teufelsmagie. Wenn es stimmt, dass er wirklich eine Armee solcher Bestien aufstellt... dann ist Donnertotem in Gefahr!", sourceObjectiveStatus = "unverified-source-field" }
