quests[45614] = { id = 45614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Reugram", description = "Unsere Verbündeten berichteten von einem Zirkel unglaublich mächtiger teufelsgeborener Bannzauberer, die die Terrasse der Tränen besetzen.\n\nIhre Anführerin, Lady Reugram, und ihre Anhänger sind Spezialisten auf dem Gebiet der uralten Magie der Nachtgeborenen und können sich Angriffen gegenüber nahezu unverwundbar machen.\n\nWir als Magier sollten allerdings in der Lage sein, sie durch Zauberraub zu besiegen. Zeigen wir ihnen die Macht der Tirisgarde!", sourceObjective = "Tötet Lady Reugram.", completion = "Die Teufelsgeborenen werden die Tirisgarde jetzt respektieren, meint Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[45615] = { id = 45615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer es findet, darf es behalten", description = "Seht Euch nur um! Was für ein Durcheinander! Überall, wo man hinsieht, liegen Haufen aus arkanem Staub!\n\n<Akazamzarak lächelt breit.>\n\nDiese armseligen Einfaltspinsel begreifen nicht, was das Zeug wert ist!\n\nIch sag Euch was: Wenn Ihr mir helft, ein paar Besen zu beschwören, um dieses Gold in Pulverform zusammenzukehren, teile ich den Gewinn mit Euch. 80:20!", sourceObjective = "Kehrt 8 Haufen arkanen Staub in der Halle des Wächters auf.", completion = "Genau so hab ich mir das vorgestellt! Ihr kennt ja die Redensart: Wo gezaubert wird, da fällt Staub!", sourceObjectiveStatus = "unverified-source-field" }
quests[45616] = { id = 45616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grievous Gladiator's Dreadplate Armor" }
