quests[45627] = { id = 45627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturz der Teufelstotems", description = "Unser Kontakt in Hochberg, Navarrogg, meldet, dass Tugar Bluttotem endlich wieder aufgetaucht ist.\n\nEr hat einen Nachrichtenkristall und einige Anweisungen für mich geschickt.\n\nIch kann Euch zu Navarrogg teleportieren und er wird Euch zu Tugars Aufenthaltsort bringen, doch es gibt ein Problem.\n\nNavarrogg braucht zusätzliche magische Kraft, um Tugars Teufelsmagie abzuwehren. Ihr werdet einige Nethersplitter benötigen, bevor Ihr abreisen könnt.", sourceObjective = "Besiegt Tugar Bluttotem. Sprecht mit Kriegsrätin Victoria, damit sie Euch zu Navarrogg teleportiert und Ihr beginnen könnt.", completion = "Donnertotem und zahllose Leben wurden gerettet. Eine weitere Krise in diesem Krieg gegen die Legion ist überstanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[45628] = { id = 45628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses Mal hinterlasst eine Spur", description = "Seid Ihr bereit, {class}t? Ich werde Euch jetzt den Plan Schritt für Schritt erklären. Ihr habt nichts zu befürchten! Aber das Wichtigste zuerst: Seht Ihr den Kletterpunkt hinter mir? Das ist Euer Weg runter in die Höhle. Viel Glück!", sourceObjective = "Seilt Euch in die Höhle ab und folgt dann Tess' Anweisungen.", completion = "Das hätte ich selbst nicht besser hinbekommen. Gute Arbeit, Schattenklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[45629] = { id = 45629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dieses Mal hinterlasst eine Spur", description = "Wird schon schiefgehen, {class}t. Wenn irgendjemand das schafft, dann Ihr... vermutlich. Nutzt den Kletterpunkt hinter mir, um Euch in die Höhle abzuseilen.\n\nWas? Seht mich doch nicht so an. Ich erkläre Euch den Rest, wenn Ihr dort seid.", sourceObjective = "Seilt Euch in die Höhle ab und folgt dann Lilians Anweisungen.", completion = "Das hätte ich selbst nicht besser hinbekommen. Gute Arbeit, Schattenklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[45630] = { id = 45630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemandes Diener", description = "Ich arbeite gerne mit Euch, {name}. Wie wäre es, wenn wir diesen Goldesel weiter melken?\n\nErzmagier Khadgar verbringt übermäßig viel Zeit damit, seine Bediensteten fortzuschicken, um wer-weiß-was zu erledigen. Wie wäre es, wenn ein geschäftstüchtiges Duo wie Ihr und ich eine billigere Alternative fänden?\n\n<Akazamzarak gibt Euch einen kleinen Kristall.>\n\nDieses feine Ding hier erschafft einen Diener praktisch aus der Luft... und ein paar Pfund des Staubs, den Ihr aufgekehrt habt.\n\nWieso nehmt Ihr ihn nicht mit in die Stadt und probiert es aus? Seht selbst!", sourceObjective = "Probiert Akazamzaraks Diener bei 5 Personen in Dalaran aus.", completion = "Mit Euch kann man richtig gute Geschäfte machen! Ich werde versuchen, den alten Khadgar für diese Sache mit den neuen Dienern zu begeistern.\n\nHa, damit mache ich ein Vermögen!\n\nOh, und Euch habe ich natürlich auch nicht vergessen. Ich hab da an etwas ganz Besonderes für Euch gedacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[45631] = { id = 45631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antonidas' Privatprojekt", description = "<Erzmagier/Erzmagierin>, ich habe etwas gefunden, das Euch vielleicht interessieren könnte: ein altes Tagebuch des verstorbenen Erzmagiers Antonidas. Darin beschreibt er ein Projekt, das wir vielleicht vollenden können.\n\nEs handelt sich dabei um eine Flugscheibe, die sich an die magische Abstimmung des Reiters anpasst.\n\nIch brauche allerdings Eure Hilfe beim Zusammentragen der Teilstücke. Wenn ich es richtig verstanden habe, hat er sie im Laufe der Jahre engen Freunden und Verbündeten überlassen. Vielleicht könnt Ihr sie davon überzeugen, uns diese Teilstücke zu überlassen.", sourceObjective = "Bergt die drei Scheiben von Antonidas' unvollendetem Projekt und kehrt dann zu Kalec in Eurer Ordenshalle zurück. Erzmagier John Nicholas am Purpursalon in Nordend über die Trischeibe des Arkanen. Sprecht mit Khadgar über Trischeibe des Feuers. Und sprecht mit Erzmagier Cedric in der Nähe des Dalarankraters über die Trischeibe des Frostes.", sourceObjectiveStatus = "unverified-source-field" }
quests[45632] = { id = 45632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst: Etrigg", description = "Habt Ihr schon von Etrigg gehört? Er ist der würdige Orckrieger, der unsere Truppen gegen die Dämonengrollnaga in der Nähe angeführt hat.\n\nLeider haben die Naga bei einem Scharmützel vor Kurzem viele unserer Krieger gefangen genommen. Etrigg ist ihnen gefolgt, doch nicht zurückgekehrt. Ich fürchte, dass ihm etwas Schreckliches zugestoßen ist.\n\nVersucht bitte, ihn zu finden!", sourceObjective = "Findet Etrigg.", completion = "Diese dreckigen Naga haben mich in einen Hinterhalt gelockt. Noch einmal werde ich nicht versagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45633] = { id = 45633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Dämonengroll", description = "Es gefällt mir nicht, dass die Naga sich mit der Brennenden Legion verbündet haben. Diese neue Entwicklung können wir nicht ignorieren.\n\nDer Nagakriegsfürst Kaz'jatar und seine Skrogkröte Teufelsbart sind für die Dämonengrollangriffe auf unsere Truppen verantwortlich.\n\nWir müssen ihnen klarmachen, dass es sich nicht auszahlt, sich mit Dämonen einzulassen!", sourceObjective = "Tötet Kriegsfürst Kaz'jatar und Teufelsbart.", completion = "Nach dem Tod ihrer Anführer werden die Dämonengrollnaga jetzt unsere {class} in Ruhe lassen. Aber wir sollten sie in Zukunft im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45634] = { id = 45634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kvaldir auf Abruf", description = "Ihr habt Helyas Horn in Helheim mit Macht erfüllt und jetzt ist die Zeit gekommen, es zu benutzen. Ich habe drei Legionsportale gefunden, die wir auslöschen sollten.\n\nMacht das Schiffswrack der Vrykul am Dämonengrollstrand ausfindig. Ruft die Kvaldir herbei und lasst sie das tun, was sie am besten können: zerstören!", sourceObjective = "Blast in Helyas Horn und weist die Kvaldir an, die drei Legionsportale zu zerstören.", completion = "Gut gemacht, {name}. Die Kvaldir werden in den kommenden Schlachten nützliche Werkzeuge sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[45637] = { id = 45637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandwurmfleisch" }
quests[45638] = { id = 45638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knusprige Spinnenbeine", progress = "Wir brauchen Fleisch – völlig egal was für Fleisch – um die Kolosse zu füttern. Die billigste Wahl ist da wohl Spinnenfleisch. In der Scherbenwelt findet Ihr Unmengen von den Viechern.", completion = "Mit Eurer Hilfe hat die Horde vielleicht 'ne Chance." }
quests[45639] = { id = 45639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kühles Fleisch", progress = "Die Fauna von Nordend hat so richtig Fleisch auf den Rippen. Geht und besorgt uns was, das wir an die Kolosse verfüttern können.", completion = "Damit läuft die Sache. Die Horde schuldet Euch was, Bruder." }
quests[45640] = { id = 45640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenschwänze" }
quests[45641] = { id = 45641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohe Tigersteaks", progress = "In Pandaria unten im Süden gibt's Tiger, die sich an kleinen Tierchen 'nen Wanst anfressen. Besorgt mir was von Ihrem Fleisch.", completion = "Ah, reiche Beute. Mein Kompliment, {class}." }
quests[45642] = { id = 45642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohes Grollhuffleisch", progress = "Von Gorchuk hab' ich gehört, dass die alten Orcklans von Draenor die Grollhufe wegen ihrer massiven Größe gemocht haben – eines von denen konnte für einen Abend ein ganzes Dorf satt machen.", completion = "Schaut Euch diesen Fleischberg an. Ihr seid echt der ganze Stolz der Horde, {name}." }
quests[45643] = { id = 45643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magere Haxen", progress = "Wir brauchen Fleisch, Unmengen Fleisch. Ihr seht ziemlich hart aus – vielleicht könnt Ihr 'n paar der fiesen Biester auf den Verheerten Inseln erlegen.", completion = "Ihr macht Euren Kriegshäuptling stolz. Für die Horde!" }
quests[45644] = { id = 45644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, meine liebste Doloria", description = "Aber hallo! Wir beide geben doch ein ganz fabelhaftes Abenteurerpaar ab, nicht wahr?\n\nJetzt, da mein Besitz in Sicherheit ist, öffnet sich uns ein neuer Weg. Ich bin ja schließlich nicht nur hergekommen, um die Dämoneninvasion zurückzuschlagen! Nein, ich bin ebenfalls auf der Suche nach meiner Liebsten, meiner holden Doloria. Als ich nach der erfolgreichen Drachenjagd kurz ruhte, hatte ich einen Traum, nein, eine Vision. Ich sah, wie Doloria in eine am Himmel schwebende Stadt entführt wurde!\n\nDas muss Dalaran sein. Beeilung, Knappe! Sattelt auf und trefft mich am berühmten Gasthaus von Dalaran. Und nun los!", sourceObjective = "Sucht Doloria im Zauberkasten in Dalaran auf.", completion = "Verdammt, ich hätte nicht gedacht, dass er mich schon wieder so schnell finden würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[45645] = { id = 45645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergebliche Mühe", description = "Öh, sicher, ja klar, ich bin eine Gefangene. Ich werde hier... gegen meinen Willen festgehalten. Oder so.\n\nAlso, mal ganz unter uns: Der alte Max hier hat keine Chance, aber trotzdem das Herz am rechten Fleck. Ich versuche ständig, mich vor ihm zu verstecken, aber er findet mich immer wieder! Und ich bring es auch nicht übers Herz, ihm einfach die Wahrheit an den Kopf schleudern.\n\nIch hab da eine Idee: Warum tötet ihr nicht ein paar dieser großen, zweiköpfigen \"Hügelbanditen\"? Sagen wir einfach, sie haben mir Schmuck gestohlen und Ihr braucht ihn, um damit Lösegeld für mich zu zahlen.\n\nLasst Euch Zeit. Und verletzt Euch nicht. Zu sehr.", progress = "Tötet \"Hügelbanditen\", um Dolorias gestohlenen \"Schmuck\" zu finden und damit ihr \"Lösegeld\" zu stellen.", completion = "<Doloria zwinkert Euch hinter ihrer Maske verschmitzt zu.>\n\nÖh, nein, ich hab sie schon ein paar Tage nicht mehr gesehen. Keine Ahnung, wovon Ihr redet." }
quests[45647] = { id = 45647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Rettungseinsatz", description = "Ich werde diese Naga für ihre Unverschämtheit büßen lassen.\n\nSie und ihre Skrogschergen haben unsere Krieger gefangen genommen, während wir gegen die Legion kämpften. Sie haben keine Ehre!\n\nWir müssen unsere gefallenen Soldaten retten, bevor sie als Sklaven verkauft werden oder Schlimmeres erleiden...", sourceObjective = "Rettet 8 Trupps gefangener Krieger.", completion = "Unsere Soldaten werden schon bald wieder in den Kampf ziehen und diese Dämonengrollnaga werden es sich zweimal überlegen, bevor sie sich wieder mit uns anlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45648] = { id = 45648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisst: Lord Darius Crowley", description = "Habt Ihr schon von Lord Darius Crowley gehört? Er ist der würdige gilnearische Krieger, der unsere Truppen gegen die Dämonengrollnaga in der Nähe angeführt hat.\n\nLeider haben die Naga bei einem Scharmützel vor Kurzem viele unserer Krieger gefangen genommen. Lord Darius ist ihnen gefolgt, doch nicht zurückgekehrt. Ich fürchte, dass ihm etwas Schreckliches zugestoßen ist.\n\nVersucht bitte, ihn zu finden!", sourceObjective = "Sucht nach Lord Darius Crowley.", completion = "Danke. Ich wurde von einem Dutzend Naga und Skrogs angegriffen! Aber zumindest konnte ich ein paar von ihnen erledigen, bevor sie mich überwältigt haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[45649] = { id = 45649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Rettungseinsatz", description = "Ich werde diese Naga für ihre Unverschämtheit büßen lassen.\n\nSie und ihre Skrogschergen haben unsere Krieger gefangen genommen, während wir gegen die Legion kämpften. Sie haben keine Ehre!\n\nWir müssen unsere gefallenen Soldaten retten, bevor sie als Sklaven verkauft werden oder Schlimmeres erleiden...", sourceObjective = "Rettet 8 Trupps gefangener Krieger.", completion = "Unsere Soldaten werden schon bald wieder in den Kampf ziehen und diese Dämonengrollnaga werden es sich zweimal überlegen, bevor sie sich wieder mit uns anlegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45650] = { id = 45650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Dämonengroll", description = "Ich bin sehr darüber besorgt, dass die Naga sich mit der Brennenden Legion verbündet haben. Diese neue Entwicklung können wir nicht ignorieren.\n\nDer Nagakriegsfürst Kaz'jatar und seine Skrogkröte Teufelsbart sind für die Dämonengrollangriffe auf unsere Truppen verantwortlich.\n\nWir müssen ihnen klarmachen, dass es sich nicht auszahlt, sich mit Dämonen einzulassen!", sourceObjective = "Tötet Kriegsfürst Kaz'jatar und Teufelsbart.", completion = "Nach dem Tod ihrer Anführer werden die Dämonengrollnaga jetzt eine Weile lang keine Angriffe mehr starten. Aber wir sollten sie in Zukunft im Auge behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[45651] = { id = 45651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Ahn'Qiraj: Ossirian" }
quests[45652] = { id = 45652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine \"bescheidene\" Anfrage", description = "{class}t, wir haben... Besuch erhalten. Sie begehrt Eintritt, doch die Wachen lassen sie nicht ohne Erlaubnis hindurch.\n\nBitte begebt Euch so bald wie möglich zur Warte.", sourceObjective = "Trefft Eure Besucherin an der Sturmaugenwarte.", completion = "Ihr habt hier das Sagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[45653] = { id = 45653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigendes Feuer" }
quests[45654] = { id = 45654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahn'Qiraj: C'Thun" }
quests[45655] = { id = 45655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Koloss von Ashi" }
quests[45656] = { id = 45656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geringe Windsteine" }
quests[45657] = { id = 45657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silithyst" }
