quests[45694] = { id = 45694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arachnozid" }
quests[45706] = { id = 45706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht Tausender", description = "Mir ist klar, dass ich hier nicht gerade beliebt bin und meine Grimmtotems und ich nicht eingeladen wurden, Euch und Euren Schamanen beizutreten, doch ich möchte Euch ein Angebot machen.\n\nDie Legion hat mein Zuhause angegriffen und ich habe ein paar Dinge verloren, die... mir sehr am Herzen liegen. Ich weiß nicht, an wen ich mich sonst wenden sollte. Es fällt mir nicht leicht, Euch um Hilfe zu bitten... aber ich habe keine Wahl. Wenn Ihr uns helft, biete ich Euch die Dienste meines Volks als Unterstützung gegen die Legion an.", sourceObjective = "Verwendet Magathas Portal und trefft Euch mit ihr in Tausend Nadeln.", completion = "Wir wollen meinen Stamm nicht warten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45723] = { id = 45723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wut der Greisin", description = "Diese Dämonen betreten mein Heim, stehlen meine Sachen und nehmen meine Leute gefangen? Nun erwartet sie meine Wut. Vernichtet sie, Kind. Zumindest dazu seid Ihr doch hoffentlich fähig.", sourceObjective = "Besiegt 15 Dämonen auf dem Düsterwolkengipfel.", completion = "Teufelsblut hat nie so süß geschmeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[45724] = { id = 45724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangen und Steine", description = "Beim Angriff der Dämonen wurden mir zwei äußerst mächtige Besitztümer genommen: mein Begleiter Arikara und der Verdammnisstein.\n\nAuch wenn Arikara den Tod nicht fürchten muss, da er keine Bedeutung für ihn hat, so wird die Legion sicher einen üblen Zweck für ihn auserkoren haben. Und der Verdammnisstein... nun, so ein mächtiges Artefakt ist in meinen Händen besser aufgehoben als in den ihren. Wir müssen uns trennen und sie finden.\n\nSeid vorsichtig, die Welt steht auf dem Spiel. Es wird nicht helfen, wenn Ihr Euch ungeschickt anstellt und alles vernichtet.", sourceObjective = "Findet entweder den Verdammnisstein oder Arikara auf dem Düsterwolkengipfel.", progress = "Seid gegrüßt, Scharfseher. Was habt Ihr gefunden?", completion = "Ich habe Arikara. Habt Ihr den Verdammnisstein gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[45725] = { id = 45725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ketten zerbrechen", description = "Die Legion wird die Grimmtotems nicht zum Narren halten. Befreit meine Leute und wir werden Euch in der kommenden Schlacht beistehen.", sourceObjective = "Befreit 8 gefangene Grimmtotems aus den Gefängniskäfigen.", completion = "Die Legion kann die Grimmtotems nicht brechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45726] = { id = 45726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die besudelte Marsch", description = "Ich habe es noch nicht geschafft, mich im Dorf umzusehen, doch im Süden werden weitere gefährliche Experimente durchgeführt. Sie besudeln die rastlosen Geister der Marsch mit noch mehr Teufelsmagie!\n\nIch werde dieses Teufelstotem so verändern, dass es den Geistern die Teufelsenergien entzieht, mit denen sie erfüllt wurden.\n\nHeilt bitte so viele Geister wie möglich, damit sie hoffentlich Frieden finden.\n\nIch kann Euch sogar dorthin befördern, wenn Ihr es möchtet!", sourceObjective = "Entzieht den Geistern der Blinden Marsch ihre Teufelsenergien.", completion = "Ihr habt diesen Seelen einen großen Gefallen getan. Ich hoffe, sie finden ihren Frieden.\n\nLasst uns nun den Experimenten direkt an deren Quelle ein Ende setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[45727] = { id = 45727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinigung der Inseln", description = "Es gibt viele Fraktionen hier auf den Verheerten Inseln. Wir müssen sie vereinen, wenn wir eine Chance gegen die Legion haben wollen. Erweist Euch ihnen gegenüber als würdig und meldet Euch dann wieder bei mir.", sourceObjective = "Sprecht mit Erzmagier Khadgar in Dalaran.", completion = "Ausgezeichnete Arbeit, {name}. Wir haben noch einen langen Weg vor uns, um diese Welt von der Legion zu befreien, aber wir sind nun einen Schritt weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[45728] = { id = 45728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Legion: Donnertotem" }
quests[45729] = { id = 45729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandwurmfleisch" }
quests[45730] = { id = 45730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knusprige Spinnenbeine" }
quests[45731] = { id = 45731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kühles Fleisch", progress = "Die Fauna Nordends ist groß, schwer und strotzt vor Fleisch. Sie eignet sich hervorragend als Futter für die Kolosse.", completion = "Damit können wir arbeiten. Die Allianz steht in Eurer Schuld." }
quests[45732] = { id = 45732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenschwänze", progress = "Es ist allgemein bekannt, dass die Krokilisken von Uldum zu den größten gehören. Benötigt man viel Fleisch in kurzer Zeit, dann ist dieser Ort die erste Wahl.", completion = "Sorgt weiter für Fleischnachschub, {name}. Wir werden jedes Stück brauchen." }
quests[45733] = { id = 45733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohe Tigersteaks" }
quests[45734] = { id = 45734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohes Grollhuffleisch", progress = "Aus Geschichten weiß ich, dass die alten Orcklans von Draenor die Grollhufe für ihre massive Größe geschätzt haben – Nur eines dieser Tiere konnte für einen Abend ein ganzes Dorf sättigen.", completion = "Nun seht Euch diesen Berg von Fleisch an. Ihr habt der Allianz alle Ehre erwiesen, {name}." }
quests[45735] = { id = 45735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magere Haxen", progress = "Wir benötigen Fleisch, große Mengen davon. Ihr seht aus, als könntet Ihr so einiges einstecken – vielleicht könnt Ihr einige der Tiere auf den Verheerten Inseln erlegen.", completion = "Ihr macht Euren König stolz. Für die Allianz!" }
quests[45736] = { id = 45736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Ahn'Qiraj: Ossirian" }
