quests[45746] = { id = 45746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errettung", description = "Das Tal wimmelt nur so von teufelsverderbten Tieren, die nicht mehr zu retten sind. Doch es gibt vielleicht noch einige, die unsere Hilfe brauchen könnten.\n\nNehmt diese Manawurzelsalbe und tragt sie bei allen Tieren auf, die Ihr seht. Wenn die Teufelsmagie sich noch nicht festgesetzt hat, könnte die Salbe vielleicht ihre Wunden heilen.", sourceObjective = "Benutzt die Manawurzelsalbe bei dämonisch infizierten Tieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[45747] = { id = 45747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche des Fürsten", description = "Diese Asche schwelt mit dem Hass, den ihr früherer Besitzer für Euch hegte.", sourceObjective = "Bringt die Asche des Fürsten zu Kriegsherr Gorchuk in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45748] = { id = 45748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perle der Tiefe", description = "Die Perle ist makellos glatt und von überraschender Dichte.", sourceObjective = "Bringt die Perle der Tiefe zu Kriegsherr Gorchuk in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45749] = { id = 45749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salz der Splitter", description = "Der abyssische Lord hat einen kleinen Haufen schwach schimmernden Sandes hinterlassen.", sourceObjective = "Bringt das Salz der Splitter zu Kriegsherr Gorchuk in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45750] = { id = 45750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied der Stürme", description = "Eine wirbelnde Essenz fließt an den Füßen des Fürsten zusammen.", sourceObjective = "Bringt das Lied der Stürme zu Kriegsherr Gorchuk in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45751] = { id = 45751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kerngeschmiedetes Siegel von Skaldrenox", description = "Die Siegel des hohen abyssischen Rats werden aus der destillierten Essenz des Elements ihrer Träger gefertigt. Dieses Siegel wurde im Feuer geschmiedet.", sourceObjective = "Bringt das kerngeschmiedete Siegel von Skaldrenox zu Kriegsherr Gorchuk in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45752] = { id = 45752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flimmerndes Siegel von Wirbelgrat", description = "Die Siegel des hohen abyssischen Rats werden aus der destillierten Essenz des Elements ihrer Träger gefertigt. Dieses Siegel wurde von den beißenden Winden geschliffen.", sourceObjective = "Bringt das flimmernde Siegel von Wirbelgrat zu Kriegsherr Gorchuk in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45754] = { id = 45754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flutsiegel von Skwol", description = "Die Siegel des hohen abyssischen Rats werden aus der destillierten Essenz des Elements ihrer Träger gefertigt. Dieses Siegel wurde aus einer Koralle gebrochen und von den Wogen der Gezeiten seidenglatt poliert.", sourceObjective = "Bringt das Flutsiegel von Skwol zu Kriegsherr Gorchuk in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
