quests[45759] = { id = 45759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kerngeschmiedetes Siegel von Skaldrenox", description = "Die Siegel des hohen abyssischen Rats werden aus der destillierten Essenz des Elements ihrer Träger gefertigt. Dieses Siegel wurde im Feuer geschmiedet.", sourceObjective = "Bringt das kerngeschmiedete Siegel von Skaldrenox zu Feldmarschall Schneefall in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45760] = { id = 45760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flimmerndes Siegel von Wirbelgrat", description = "Die Siegel des hohen abyssischen Rats werden aus der destillierten Essenz des Elements ihrer Träger gefertigt. Dieses Siegel wurde von den beißenden Winden geschliffen.", sourceObjective = "Bringt das flimmernde Siegel von Wirbelgrat zu Feldmarschall Schneefall in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45761] = { id = 45761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diamantsiegel von Kazum", description = "Die Siegel des hohen abyssischen Rats werden aus der destillierten Essenz des Elements ihrer Träger gefertigt. Dieses Siegel wurde aus Stein gemeißelt und zu einem lupenreinen Diamanten verdichtet.", sourceObjective = "Bringt das Diamantsiegel von Kazum zu Feldmarschall Schneefall in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[45763] = { id = 45763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonische Störung", description = "Während unserer Aufklärungsmission an der Verheerten Küste haben wir etwas Besorgniserregendes beobachtet.\n\nDie Legion versucht, die Macht von Azeroths Elementen für sich zu nutzen. Und es scheint ihr sogar zu gelingen.\n\nWir müssen sie um jeden Preis aufhalten. Ich kann ein Portal für Euch öffnen, damit Ihr Euch mit Therazane an der Teufelsgarnison treffen könnt. Sie wird Euch die Situation näher erklären.", sourceObjective = "Sprecht mit Scharfseher Nobundo, um zur Verheerten Küste zu reisen und Euch dann mit Therazane an der Teufelsgarnison zu treffen.", completion = "Die Legion will Azeroth ihrem Willen unterwerfen. Wir dürfen das nicht länger zulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[45764] = { id = 45764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Lot bringen", description = "Kor'vass hat einen Bericht über den Status der Teufelsshammer übersandt. Sie hat großen Schaden erlitten und sieht jetzt noch hässslicher aus alss zuvor, auch wenn dasss kaum vorstellbar sein mag...\n\nUnd sie neigt sich auch ein wenig auf die Seite, wass recht drollig aussieht, wie ich finde. Aber auss irgendeinem Grund findet das Kor'vass gar nicht so amüsant.\n\nAuf jeden Fall befinden sich in der Umgebung des Grabmalss des Sargerass stabilisierende Kristalle, die sie für Reparaturen verwenden könnte.\n\nEin Wort von Euch und ich lassse Euch von einer Einheit Fledermaussreiter der Illidari dorthinbegleiten. Ich würde ja auch kommen, aber...", sourceObjective = "Beschafft 3 stabilisierende Kristalle.", progress = "Habt Ihr die Materialien für die Reparaturen an der Teufelsshammer beschafft, {name}?", completion = "Eine Sschande, dasss die Fledermaussreiter ess nicht überstanden haben. Ein Grund mehr, die Legion in Sschutt und Asche zu legen, sobald der Waffenkern der Teufelsshammer wieder einsatzbereit isst!", sourceObjectiveStatus = "unverified-source-field" }
quests[45765] = { id = 45765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brüder und Schwestern", description = "Eure Leute haben versucht, die Legion aufzuhalten, bevor Ihr eingetroffen seid, aber das Fleisch ist schwach und sie haben zu viele Wunden erlitten. Ohne Euren Beistand werden sie mit Sicherheit durch die Hände der Dämonen sterben. Geht und helft ihnen.", sourceObjective = "Heilt 8 verletzte Schamanen in der Teufelsgarnison.", completion = "Ich habe für Deckung gesorgt, während sich die schwächeren Eurer Leute zurückzogen. Sie werden sicher zum Mahlstrom zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[45766] = { id = 45766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Albino Elderhorn" }
quests[45767] = { id = 45767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarkerne", description = "Die Eredar hier missbrauchen die Macht aller Elemente Azeroths und zwingen sie durch ihre Teufelsmagie, ihnen zu Willen zu sein. Das erreichen sie mithilfe der Kuriositäten, die die Legion entwickelt hat: Machtkerne, die zu jeweils einem Element passen.\n\nLasst nicht zu, dass die Legion weiter unsere Welt missbraucht. Tötet sie und nehmt ihnen die Quellen ihrer Macht ab.", sourceObjective = "Sammelt 3 Feuerkraftkerne, 3 Wasserkraftkerne, 3 Erdkraftkerne und 3 Luftkraftkerne.", progress = "Niemand sollte die Elemente seinem Willen unterwerfen. Zeigt der Legion, wie fehlgeleitet ihre Vorstellungen sind.", completion = "Der Verdammnisstein scheint vor lauter Energie zu pulsieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[45769] = { id = 45769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großbrand", description = "Dieser Unhold! Auf dem Hügel macht sich ein Dämon, der sich \"Flammenspalter\" nennt, die Macht meines Reichs zunutze. Eure Schamanen sterben, während er den Feuerlanden die Macht entzieht und das Feuer unserer Welt mit der unheiligen Flamme seiner eigenen vermischt.\n\nEr ist äußerst mächtig, <Scharfseher/Scharfseherin>. Ihr müsst ihn zur Strecke bringen, koste es, was es wolle!", sourceObjective = "Tötet Barastagax den Flammenspalter.", completion = "Ah, Ihr seid erwacht. Man hat mir bereits zugetragen, was geschehen ist.", sourceObjectiveStatus = "unverified-source-field" }
